body.large-text {
  --font-scale: 1.25;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: var(--font-sans);
  background-color: #0F172A; /* Outer background - dark slate */
